{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Ketoprofen, a lipophilic acidic aryl-ketone, has an absolute oral bioavailability of at least 92% in humans; its high transferability and shared acidic/lipophilic aromatic character support high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Suprofen, a close aryl-propionic acid ketone analogue, shows 92.2% absolute oral bioavailability with no significant first-pass effect, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Terodiline, a lipophilic drug, has a mean absolute oral bioavailability of 92% (range 64-105%) in healthy volunteers, supporting essentially complete oral absorption for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Diphenhydramine, despite moderate first-pass metabolism, has about 60% oral bioavailability in humans, confirming that lipophilic small molecules with this transfer profile are high at the F>=20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Labetalol has a low oral bioavailability of 18% due to high first-pass metabolism; this is the main contradictory anchor, but its phenolic/ethanolamine structure and extensive presystemic conjugation are not shared by the query, so it does not overturn the high-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is warfarin, a small lipophilic acidic 4-hydroxycoumarin. High-transfer analogues with similar lipophilic acidic/aromatic character (ketoprofen, suprofen) and lipophilic drugs with near-complete absorption (terodiline) strongly support high oral bioavailability; the only low-F anchor (labetalol) reflects a distinct first-pass liability not present in the query.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is provided; prediction relies on high-transfer analogues.",
    "The low-F labetalol record is mechanistically distinct, but its high transfer score introduces some uncertainty about how much weight to place on first-pass metabolism differences."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

